{
  "summary": "Ahlan! Nchallah n3awnek t7ell el moshkila mta3 el bag, el téléphone w el carte bancaire li tfa9douhom fel taxi.",
  "steps": [
    {
      "when": "now",
      "action": "Appelez le service client de votre banque (numéro au dos de la carte ou via l'application) pour faire opposition immédiate de la carte bancaire [1]",
      "cites": [1]
    },
    {
      "when": "now",
      "action": "Bloquez le téléphone à distance avec \"Find My\" (iPhone) ou \"Find My Device\" (Android) et changez les mots de passe des comptes sensibles [3]",
      "cites": [3]
    },
    {
      "when": "now",
      "action": "Contactez votre opérateur (Tunisie Telecom, Ooredoo ou Orange Tunisie) depuis un autre téléphone pour suspendre la carte SIM et demander une nouvelle SIM en agence avec votre pièce d’identité [3]",
      "cites": [3]
    },
    {
      "when": "now",
      "action": "Déposez une plainte au poste de police le plus proche (urgence 197) en indiquant le numéro IMEI du téléphone et la description du bag contenant les objets [3,5]",
      "cites": [3,5]
    },
    {
      "when": "today",
      "action": "Rendez-vous à votre agence bancaire avec le récépissé de plainte pour demander l’émission d’une nouvelle carte bancaire [1]",
      "cites": [1]
    },
    {
      "when": "today",
      "action": "Déclarez la perte du bag (et de son contenu) sur la plateforme Lqitha en précisant couleur, marque, signes distinctifs et le lieu (taxi) [5]",
      "cites": [5]
    },
    {
      "when": "today",
      "action": "Si vous avez un reçu ou l’identifiant du chauffeur de taxi, contactez‑le via l’application de réservation ou le numéro indiqué pour tenter de récupérer le bag [5]",
      "cites": [5]
    },
    {
      "when": "later",
      "action": "Demandez à la police le récépissé de déclaration de perte pour le présenter aux éventuelles démarches administratives (ex. renouvellement de documents) [6]",
      "cites": [6]
    }
  ],
  "documents": [
    "Récépissé de plainte de police",
    "Pièce d’identité (CIN ou passeport) pour la demande de nouvelle carte SIM",
    "Numéro IMEI du téléphone"
  ],
  "deadlines": [],
  "coverage": [
    {"item": "bank_card", "covered": true},
    {"item": "phone", "covered": true},
    {"item": "bag", "covered": true}
  ],
  "letter": {
    "type": "police_declaration",
    "title": "Déclaration de perte d'objets dans un taxi",
    "body": "Je soussigné(e) [Nom] [Prénom], titulaire de la carte d'identité nationale n° [N° CIN], résidant à [Adresse], déclare avoir perdu le [date_iso] à [heure approximative] dans un taxi à Tunis. Le bag contenait un téléphone mobile (marque, modèle, IMEI *#06#) et une carte bancaire. Je joins le récépissé de plainte et demande l’enregistrement de cette perte.\n\nFait à Tunis, le [date_iso]\nSignature : __________________"
  }
}
